/** static void SpriteCB_Flicker(struct Sprite *sprite) */
export function SpriteCB_Flicker(sprite: any): any {
  sprite.sDelay--;
      if (sprite.sDelay == 0)
      {
          sprite.sDelay = 8;
          sprite.invisible ^= 1;
          sprite.sNumFlickers--;
          if (sprite.sNumFlickers == 0)
          {
              sprite.invisible = FALSE;
              sprite.callback = SpriteCallbackDummy_2;
              sFlickerArray[0] = 0;
          }
      }
}

/** void SpriteCB_FaintOpponentMon(struct Sprite *sprite) */
export function SpriteCB_FaintOpponentMon(sprite: any): any {
  let battler: any = sprite.sBattler;
      let species: any = null;
      let yOffset: any = null;

      if (gBattleSpritesDataPtr.battlerData[battler].transformSpecies != 0)
          species = gBattleSpritesDataPtr.battlerData[battler].transformSpecies;
      else
          species = sprite.sSpeciesId;

      GetMonData(gEnemyParty[gBattlerPartyIndexes[battler]], MON_DATA_PERSONALITY);   

      if (species == (201))
      {
          let personalityValue: any = GetMonData(gEnemyParty[gBattlerPartyIndexes[battler]], MON_DATA_PERSONALITY);
          let unownForm: any = GET_UNOWN_LETTER(personalityValue);
          let unownSpecies: any = null;

          if (unownForm == 0)
              unownSpecies = (201);   
          else
              unownSpecies = ((412)) + unownForm;   

          yOffset = gMonFrontPicCoords[unownSpecies].y_offset;
      }
      else if (species == (385))
      {
          yOffset = gCastformFrontSpriteCoords[gBattleMonForms[battler]].y_offset;
      }
      else if (species > ((412)))
      {
          yOffset = gMonFrontPicCoords[(0)].y_offset;
      }
      else
      {
          yOffset = gMonFrontPicCoords[species].y_offset;
      }

      sprite.data[3] = 8 - yOffset / 8;
      sprite.data[4] = 1;
      sprite.callback = SpriteCB_AnimFaintOpponent;
}

/** static void SpriteCB_AnimFaintOpponent(struct Sprite *sprite) */
export function SpriteCB_AnimFaintOpponent(sprite: any): any {
  let i: any = null;

      if (--sprite.data[4] == 0)
      {
          sprite.data[4] = 2;
          sprite.y2 += 8;  
          if (--sprite.data[3] < 0)
          {
              FreeSpriteOamMatrix(sprite);
              DestroySprite(sprite);
          }
          else  
          {
              let dst: any = gMonSpritesGfxPtr.sprites.byte[GetBattlerPosition(sprite.sBattler)] + (gBattleMonForms[sprite.sBattler] << 11) + (sprite.data[3] << 8);

              for (i = 0; i < 0x100; i++)
                  dst =  0;

              StartSpriteAnim(sprite, gBattleMonForms[sprite.sBattler]);
          }
      }
}

